create table `chatbot_reports` (`id` char(26) not null, `name` varchar(255) not null, `type` varchar(30) not null, `config` json not null, `data` json null, `schedule` varchar(30) null, `recipients` json null, `created_by` char(26) null, `last_generated_at` timestamp null, `deleted_at` timestamp null, `created_at` timestamp null, `updated_at` timestamp null, primary key (`id`));
create table `chatbot_agent_statuses` (`id` char(26) not null, `user_id` char(26) not null, `status` varchar(20) not null default 'offline', `away_reason` varchar(255) null, `active_chats` int not null default '0', `max_chats` int not null default '5', `available_at` timestamp null, `last_active_at` timestamp null, `logged_in_at` timestamp null, `logged_out_at` timestamp null, `created_at` timestamp null, `updated_at` timestamp null, primary key (`id`));
create table `chatbot_agent_performance` (`id` char(26) not null, `user_id` char(26) not null, `date` date not null, `conversations_count` int not null default '0', `tickets_resolved` int not null default '0', `messages_sent` int not null default '0', `avg_response_time_seconds` int not null default '0', `avg_resolution_time_seconds` int not null default '0', `satisfaction_score` decimal(3, 2) not null default '0', `chats_handoff` int not null default '0', `missed_chats` int not null default '0', `total_online_seconds` int not null default '0', `metrics` json null, `created_at` timestamp null, `updated_at` timestamp null, primary key (`id`));
create table `chatbot_audit_logs` (`id` char(26) not null, `user_id` char(26) null, `action` varchar(255) not null, `resource_type` varchar(255) not null, `resource_id` varchar(36) null, `old_values` json null, `new_values` json null, `ip_address` varchar(45) null, `user_agent` varchar(255) null, `created_at` timestamp null, `updated_at` timestamp null, primary key (`id`));
create table `personal_access_tokens` (`id` bigint unsigned not null auto_increment primary key, `tokenable_type` varchar(255) not null, `tokenable_id` bigint unsigned not null, `name` text not null, `token` varchar(64) not null, `abilities` text null, `last_used_at` timestamp null, `expires_at` timestamp null, `created_at` timestamp null, `updated_at` timestamp null);
create table `chatbot_canned_responses` (`id` char(26) not null, `shortcut` varchar(50) not null, `body` text not null, `category` varchar(50) null, `department_id` char(26) null, `created_by` bigint unsigned null, `created_at` timestamp null, `updated_at` timestamp null, primary key (`id`));
create table `chatbot_form_fields` (`id` char(26) not null, `label` varchar(255) not null, `field_key` varchar(100) not null, `field_type` varchar(50) not null, `placeholder` varchar(255) null, `options` json null, `is_required` tinyint(1) not null default '0', `sort_order` int not null default '0', `is_active` tinyint(1) not null default '1', `created_at` timestamp null, `updated_at` timestamp null, primary key (`id`));
create table `api_tokens` (`id` bigint unsigned not null auto_increment primary key, `name` varchar(255) not null, `token` varchar(64) not null, `permissions` text null, `rate_limit` int not null default '60', `expires_at` timestamp null, `revoked_at` timestamp null, `created_by` bigint unsigned null, `created_at` timestamp null, `updated_at` timestamp null);
create table `analytics_events` (`id` bigint unsigned not null auto_increment primary key, `event_type` varchar(255) not null, `session_id` varchar(255) null, `metadata` text null, `created_at` timestamp null, `updated_at` timestamp null);

