INSERT INTO `testimonials` (`id`, `author`, `role`, `quote`, `photo`, `sort_order`, `is_published`, `created_at`, `updated_at`, `deleted_at`, `name`, `student_name`, `class`, `relation`, `phone`, `email`, `title`, `testimonial`, `rating`, `image`, `status`, `featured`, `display_location`, `approved_by`, `approved_at`, `ip_address`, `browser`, `is_verified`, `rejection_reason`) VALUES 
('01kxfnx5f52a03ahywrprv18ja', 'Ms. Pinki', NULL, 'Prayaag International School provides a well-rounded education that prepares children for the future. The school’s commitment to innovation, technology integration, and experiential learning makes it stand out among the top schools in Panipat.', NULL, 1, 1, '2026-07-14 06:44:22', '2026-07-14 06:44:22', NULL, 'Ms. Pinki', 'Shelly', 'IX H', 'Mother', '9999999901', 'pinki@gmail.com', 'Well-rounded Education', 'Prayaag International School provides a well-rounded education that prepares children for the future. The school’s commitment to innovation, technology integration, and experiential learning makes it stand out among the top schools in Panipat.', 5, NULL, 'approved', 1, '["home","testimonials"]', NULL, NULL, NULL, NULL, 0, NULL),
('01kxfnx5y6yxtfecs6g8hr7gq7', 'Mr. Kamal Chuge', NULL, 'Choosing Prayaag International School for our child has been one of the best decisions we made as parents. The school’s caring and supportive staff, excellent infrastructure, and consistent academic achievements make it the top choice in Panipat.', NULL, 2, 1, '2026-07-14 06:44:22', '2026-07-14 06:44:22', NULL, 'Mr. Kamal Chuge', 'Felix', 'VII H', 'Father', '9999999902', 'kamal@gmail.com', 'Best Decision', 'Choosing Prayaag International School for our child has been one of the best decisions we made as parents. The school’s caring and supportive staff, excellent infrastructure, and consistent academic achievements make it the top choice in Panipat.', 5, NULL, 'approved', 1, '["home","testimonials"]', NULL, NULL, NULL, NULL, 0, NULL),
('01kxfnx6bn5wyyt4h9g7xe50vs', 'Ms. Rajni', NULL, 'Prayaag International School’s commitment to holistic education is commendable. The school’s focus on sports, arts, and cultural activities, along with academics, ensures that children receive a well-balanced education that prepares them for life.', NULL, 3, 1, '2026-07-14 06:44:23', '2026-07-14 06:44:23', NULL, 'Ms. Rajni', 'Diksha', 'IX Z', 'Mother', '9999999903', 'rajni@gmail.com', 'Holistic Education', 'Prayaag International School’s commitment to holistic education is commendable. The school’s focus on sports, arts, and cultural activities, along with academics, ensures that children receive a well-balanced education that prepares them for life.', 5, NULL, 'approved', 1, '["home","testimonials"]', NULL, NULL, NULL, NULL, 0, NULL),
('01kxfnx6qpzcy7wzy4w454ds8p', 'Ms. Neelam', NULL, 'I can confidently say that Prayaag International School is the best school in Panipat for promoting a love for learning. The teachers create an engaging and stimulating environment, fostering a passion for knowledge among the students.', NULL, 4, 1, '2026-07-14 06:44:23', '2026-07-14 06:44:23', NULL, 'Ms. Neelam', 'Bhumi', 'IX H', 'Mother', '9999999904', 'neelam@gmail.com', 'Love for Learning', 'I can confidently say that Prayaag International School is the best school in Panipat for promoting a love for learning. The teachers create an engaging and stimulating environment, fostering a passion for knowledge among the students.', 5, NULL, 'approved', 1, '["home","testimonials"]', NULL, NULL, NULL, NULL, 0, NULL),
('01kxfnx748kdbytvwqv69t8yg6', 'Mr. Pratap Singh', NULL, 'Prayaag International School has a fantastic support system for students with different abilities. The inclusive approach and personalized attention given to each child make it a top school in Panipat for catering to diverse learning needs.', NULL, 5, 1, '2026-07-14 06:44:23', '2026-07-14 06:44:23', NULL, 'Mr. Pratap Singh', 'Devika', 'XI H', 'Father', '9999999905', 'pratap@gmail.com', 'Fantastic Support System', 'Prayaag International School has a fantastic support system for students with different abilities. The inclusive approach and personalized attention given to each child make it a top school in Panipat for catering to diverse learning needs.', 5, NULL, 'approved', 1, '["home","testimonials"]', NULL, NULL, NULL, NULL, 0, NULL),
('01kxfnx7h9p8yzwdar9wszhptr', 'Mr. Vishal Garg', NULL, 'We are extremely satisfied with our decision to enroll our child in Prayaag International School. The school’s strong focus on values, ethics, and discipline, combined with excellent academic programs, makes it the best choice in Panipat.', NULL, 6, 1, '2026-07-14 06:44:24', '2026-07-14 06:44:24', NULL, 'Mr. Vishal Garg', 'Shalok Garg', 'X P', 'Father', '9999999906', 'vishal@gmail.com', 'Strong Focus on Values', 'We are extremely satisfied with our decision to enroll our child in Prayaag International School. The school’s strong focus on values, ethics, and discipline, combined with excellent academic programs, makes it the best choice in Panipat.', 5, NULL, 'approved', 1, '["home","testimonials"]', NULL, NULL, NULL, NULL, 0, NULL),
('01kxj5405e3ph0qrdvj7j93gr8', 'Dheeraj', NULL, 'Choosing Prayaag International School for our child has been one of the best decisions we have made. The dedicated teachers, modern learning environment, and focus on academics as well as values have helped our child grow into a confident and responsible individual. We truly appreciate the school\'s commitment to excellence.', 'uploads/testimonials/main_parent_6a571f3af1849.jpeg', 7, 1, '2026-07-15 05:48:43', '2026-07-15 05:49:49', NULL, 'Dheeraj', 'Tanveet', '1st', 'Father', '9896363292', 'dheeraj@gmail.com', NULL, 'Choosing Prayaag International School for our child has been one of the best decisions we have made. The dedicated teachers, modern learning environment, and focus on academics as well as values have helped our child grow into a confident and responsible individual. We truly appreciate the school\'s commitment to excellence.', 5, 'uploads/testimonials/main_parent_6a571f3af1849.jpeg', 'approved', 0, '["home","testimonials"]', '01kwxw36d5518sw7ctxzzh279c', '2026-07-15 05:49:49', '127.0.0.1', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36', 0, NULL);
